const WORKSPACE_DATASET_STORE='datasets';
function openWorkspaceDb(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(new Error('IndexedDB unavailable'));const req=indexedDB.open(WORKSPACE_DB_NAME,WORKSPACE_DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(WORKSPACE_DATASET_STORE))db.createObjectStore(WORKSPACE_DATASET_STORE,{keyPath:'key'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('Unable to open IndexedDB'));req.onblocked=()=>reject(new Error('IndexedDB upgrade blocked'));});}
async function workspaceDbGet(key){const db=await openWorkspaceDb();return new Promise((resolve,reject)=>{const tx=db.transaction(WORKSPACE_DATASET_STORE,'readonly'),req=tx.objectStore(WORKSPACE_DATASET_STORE).get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error||new Error('IndexedDB read failed'));tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();reject(tx.error||new Error('IndexedDB read aborted'));};});}
async function workspaceDbPut(record){const db=await openWorkspaceDb();return new Promise((resolve,reject)=>{const tx=db.transaction(WORKSPACE_DATASET_STORE,'readwrite');tx.objectStore(WORKSPACE_DATASET_STORE).put(record);tx.oncomplete=()=>{db.close();resolve(true);};tx.onerror=()=>{db.close();reject(tx.error||new Error('IndexedDB write failed'));};tx.onabort=()=>{db.close();reject(tx.error||new Error('IndexedDB write aborted'));};});}
async function workspaceDbDelete(key){const db=await openWorkspaceDb();return new Promise((resolve,reject)=>{const tx=db.transaction(WORKSPACE_DATASET_STORE,'readwrite');tx.objectStore(WORKSPACE_DATASET_STORE).delete(key);tx.oncomplete=()=>{db.close();resolve(true);};tx.onerror=()=>{db.close();reject(tx.error||new Error('IndexedDB delete failed'));};tx.onabort=()=>{db.close();reject(tx.error||new Error('IndexedDB delete aborted'));};});}
async function persistWorkspaceDataset(key,payload){try{await workspaceDbPut({key,schemaVersion:1,...payload});return true;}catch(err){console.warn('KeywordOS browser persistence unavailable',err);return false;}}
async function restorePersistentImports(){try{const [ads,finance]=await Promise.all([workspaceDbGet('ads'),workspaceDbGet('finance')]);if(ads?.schemaVersion===1&&Array.isArray(ads.rows)&&ads.rows.length){state.currentRows=clone(ads.rows);state.adsSource=ads.source||'Browser import';state.adsImportedAt=ads.importedAt||'';state.adsPersistent=true;}if(finance?.schemaVersion===1&&Array.isArray(finance.rows)&&finance.rows.length){state.financeRows=clone(finance.rows);state.financeSource=finance.source||'Browser import';state.financeImportedAt=finance.importedAt||'';state.financePersistent=true;}}catch(err){console.warn('KeywordOS persistent import restore skipped',err);}}
async function resetPersistentDataset(kind){try{await workspaceDbDelete(kind);}catch(err){console.warn('KeywordOS persistent dataset reset failed',err);toast('Unable to clear the browser-persisted dataset; reset cancelled','error');return;}if(kind==='ads'){state.currentRows=clone(SEED.rows||[]);state.adsSource='Cloudflare seed · 202606.csv';state.adsImportedAt='';state.adsPersistent=false;state.importPreview=null;state.range='30';$('#range-select').value='30';logEvent('Data Import Reset','Amazon Ads','Restored Cloudflare seed dataset','Manual','Import');toast('Amazon Ads workspace reset to Cloudflare seed','success');state.page='import';render();return;}state.financeRows=clone(FIN_SEED.rows||[]);state.financeSource=FIN_SEED.meta?.source||'Unified Report';state.financeImportedAt='';state.financePersistent=false;state.financeImportPreview=null;state.financePageNo=1;state.financeSearch='';logEvent('Unified Report Reset','Unified Transaction','Restored Cloudflare seed dataset','Manual','Import');toast('Unified Report reset to Cloudflare seed','success');render();}

