function v8Kpi(label,value,sub,tone=''){return `<div class="v8-kpi ${tone}"><span>${label}</span><b>${value}</b><small>${sub}</small></div>`;}
function storeCard(s){const m=storeMetricPreview(s);return `<button class="store-card ${s.status==='Connected'?'connected':'preview'}" data-switch-store="${s.id}"><div class="store-card-top"><span class="store-flag">${s.flag}</span><div><b>${esc(s.name)}</b><small>${esc(s.marketplace)} · ${esc(s.code)}</small></div>${s.demo?'<span class="badge gray">UI PREVIEW</span>':'<span class="badge green">CONNECTED</span>'}</div>${s.status==='Connected'?`<div class="store-metrics"><div><span>Spend</span><b>${fmtMoney(m.spend)}</b></div><div><span>Sales</span><b>${fmtMoney(m.sales)}</b></div><div><span>ACoS</span><b>${fmtPct(m.acos)}</b></div><div><span>Orders</span><b>${fmtInt(m.orders)}</b></div></div>`:`<div class="store-empty"><b>Ready for independent authorization</b><span>${s.connection} reserved · no Amazon token stored</span></div>`}<div class="store-boundary"><span>${s.connection}</span><i>→</i><span>${s.advertiser}</span><i>→</i><span>${s.marketplace}</span></div></button>`;}
function globalOpportunityRows(){const terms=(SEED.searchTerms||[]).slice(0,40);return terms.map((t,i)=>({term:t.term,level:i%9===0?'Risk':t.orders>=8&&t.acos<.45?'High':'Watch',note:i%9===0?'Strong in Store 01; review before negative use elsewhere':`${t.orders} orders · ${fmtPct(t.acos)} ACoS in connected Store`})).sort((a,b)=>a.level==='High'?-1:1);}
