 campaign:[['name','Campaign','left'],['status','Status','center'],['portfolio','Portfolio','left'],['targetClass','Targeting','left'],['adGroups','Ad Groups'],['targets','Targets'],['avgBid','Avg Bid'],['spend','Spend'],['sales','Sales'],['acos','ACoS'],['roas','ROAS'],['orders','Orders'],['cvr','CVR'],['cpc','CPC']],
 adgroup:[['name','Ad Group','left'],['campaign','Campaign','left'],['status','Status','center'],['targetClass','Targeting','left'],['targets','Targets'],['avgBid','Avg Bid'],['spend','Spend'],['sales','Sales'],['acos','ACoS'],['orders','Orders'],['cvr','CVR'],['cpc','CPC']],
 target:[['name','Target','left'],['matchType','Match Type','left'],['status','Status','center'],['campaign','Campaign','left'],['adGroup','Ad Group','left'],['bid','Bid'],['impressions','Impressions'],['clicks','Clicks'],['spend','Spend'],['sales','Sales'],['acos','ACoS'],['orders','Orders'],['cvr','CVR']],
